// Indexed by Provider, then small and large.
static const uint8_t *const maps[][2] = {
  { nullptr, nullptr },
  { anthropic_14, anthropic_30 },
  { openai_14, openai_30 },
  { cursor_14, cursor_30 },
  { openrouter_14, openrouter_30 },
  { nullptr, nullptr },
};

static lv_img_dsc_t images[sizeof(maps) / sizeof(maps[0])][2];

const lv_img_dsc_t *logoFor(Provider provider, bool large) {
  if (provider >= sizeof(maps) / sizeof(maps[0]) || !maps[provider][large]) {
    return nullptr;
  }
  int side = large ? LOGO_LARGE : LOGO_SMALL;
  lv_img_dsc_t &image = images[provider][large];
  image.header.cf = LV_IMG_CF_TRUE_COLOR;
  image.header.w = side;
  image.header.h = side;
  image.data_size = side * side * 2;
  image.data = maps[provider][large];
  return &image;
}
